INSERT INTO official_account_posts (post_id, account_id, title, summary, url, published_at) VALUES ('post_strr_1', 'oa_strr_customs', 'personal lithium-battery shipping and declaration guide', 'air shipment of lithium-battery items is limited by rated energy (Wh)，over-limit items cannot be shipped by air；declare the item name and value accurately。', 'https://customs.example/li-battery-notice', '2026-06-08');
INSERT INTO official_account_posts (post_id, account_id, title, summary, url, published_at) VALUES ('post_strr_2', 'oa_strr_brand', 'official warranty, certification, and overseas support', 'the stroller must meet brake and safety-harness standards；some batches were recalled for non-compliant brakes。verify recalls and standards by production batch，three handling options are available: recall replacement, reinforcement accessory, or return。', 'https://brand.example/notice', '2026-06-08');
INSERT INTO official_account_posts (post_id, account_id, title, summary, url, published_at) VALUES ('post_strr_3', 'oa_strr_card', 'foreign and overseas card safety tips', 'foreign-currency postings may have exchange-rate and timing differences；if duplicate charges or an unknown merchant appear, verify promptly and consider a dispute。', 'https://card.example/fx-safety', '2026-06-08');
INSERT INTO official_account_posts (post_id, account_id, title, summary, url, published_at) VALUES ('post_strr_4', 'oa_strr_brand', 'three-option handling comparison', 'recall replacement costs ¥0，expected duration about two weeks；brake accessory reinforcement costs ¥120，can be self-installed；returnsrefund follows the original payment path，a replacement must be purchased separately。', 'https://brand.example/options', '2026-06-08');
